import math
import numpy as np


def winding_number(gamma, dgamma, a, t_end, n=2000):
    t = np.linspace(0, t_end, n + 1)
    total = np.trapezoid(dgamma(t) / (gamma(t) - a), t)
    return int(round((total / (2 * math.pi)).real))

